import {esc} from './model.js';
import {createMolecule,moleculeFormula,validateMolecule,removeAtom,elements} from './molecule.js';
import {renderMolecule} from './molecule-preview.js';
const toolPaths={select:'M5 3v17l5-6 7-2Z',atom:'M12 3v18M3 12h18',erase:'m4 15 9-11 7 6-9 11H8Zm4-4 7 6',undo:'m9 5-5 5 5 5M4 10h10a6 6 0 0 1 0 12',redo:'m15 5 5 5-5 5M20 10H10a6 6 0 0 0 0 12',clear:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',single:'M3 18 21 6',double:'M3 15 19 3M5 21 21 9',triple:'M2 14 17 3M5 18 20 7M8 22 23 11',ring:'m12 3 9 5v9l-9 5-9-5V8ZM7 9l5-3 5 3m0 6-5 3-5-3'};
const glyph=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${toolPaths[k]}"/></svg>`;
export function openMicroModeling(openDialog,initial,{title='微观建模',materialName='',onApply,readOnly=false}={}){
 let draft=structuredClone(initial),tool='select',element='C',selected=null,bondStart=null,showH=false,drag=null;const undo=[],redo=[];
 const button=(action,label)=>`<button type="button" data-micro-action="${action}" aria-label="${label}" title="${label}">${glyph(action)}</button>`;
 const d=openDialog(`<div class="micro-modeling-content"><header class="micro-modeling-header"><div><h2>${esc(title)}</h2><p>${materialName?'对应材料：'+esc(materialName)+' · ':''}分子建模示意</p></div></header><div class="micro-modeling-split"><section class="micro-2d-panel" aria-label="二维分子式编辑"><div class="micro-pane-title"><strong>分子式编辑</strong><label><input type="checkbox" data-show-h> 显示氢原子</label></div><div class="micro-edit-tools" role="toolbar" aria-label="分子基础编辑工具">${button('select','选择与移动原子')}${button('atom','添加原子')}${button('erase','删除原子或键')}<i></i>${button('undo','撤销分子修改')}${button('redo','重做分子修改')}${button('clear','清空分子')}<select aria-label="分子示例" data-micro-preset><option value="">选择示例</option><option value="butane">丁烷</option><option value="ethanol">乙醇</option><option value="benzene">苯</option></select></div><div class="micro-drawing-space"><div class="micro-bond-tools" role="toolbar" aria-label="化学键与环工具">${button('single','绘制单键')}${button('double','绘制双键')}${button('triple','绘制三键')}<i></i>${button('ring','苯环模板')}</div><svg class="micro-formula-canvas" viewBox="0 0 500 360" aria-label="二维分子结构，点击原子编辑或在空白处添加" tabindex="0"></svg><div class="micro-element-tools" role="toolbar" aria-label="元素选择">${elements.map(el=>`<button type="button" data-element="${el}" aria-label="选择元素 ${el}">${el}</button>`).join('')}</div></div><div class="micro-formula-info"><span data-micro-tool-status></span><strong data-micro-formula></strong></div><div class="micro-atom-inspector"><label>分子名称<input data-micro-name value="${esc(draft.name)}" maxlength="40"></label><span data-selected-atom>未选中原子</span></div></section><section class="micro-3d-panel" aria-label="三维分子模型预览"><div class="micro-pane-title"><strong>模型预览</strong><span>3D 球棍模型</span></div><div class="micro-molecule-preview"></div></section></div><footer class="micro-modeling-footer"><div><p class="micro-edit-error" role="alert"></p><small>原型示意：支持基础绘制与预览，未进行化学价校验，不代表真实材料分子结构。</small></div><div class="dialog-actions"><button type="button" class="btn" data-dialog-close>取消</button><button type="button" class="btn primary" data-apply-molecule>应用模型</button></div></footer></div>`);d.classList.add('micro-modeling-dialog');
 const svg=d.querySelector('.micro-formula-canvas'),viewer=renderMolecule(d.querySelector('.micro-molecule-preview'),draft,{height:()=>Math.max(260,Math.min(400,innerHeight*.45))});
 function remember(){undo.push(structuredClone(draft));redo.length=0;}
 function setTool(next){tool=next;bondStart=null;sync();}
 function sync(){d.querySelectorAll('[data-micro-action]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.microAction===tool)));d.querySelectorAll('[data-element]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.element===element)));d.querySelector('[data-micro-action=undo]').disabled=!undo.length;d.querySelector('[data-micro-action=redo]').disabled=!redo.length;d.querySelector('[data-micro-tool-status]').textContent={select:'选择原子，可拖动移动',atom:'点击空白处添加 '+element,erase:'点击原子或键删除',single:'依次点击两个原子连接单键',double:'依次点击两个原子连接双键',triple:'依次点击两个原子连接三键'}[tool]||'基础编辑';d.querySelector('[data-selected-atom]').textContent=selected!==null&&draft.atoms[selected]?'当前原子：'+draft.atoms[selected].element+' '+(selected+1):'未选中原子';}
 function draw(){
 const shown=draft.atoms.map((a,i)=>({...a,index:i})).filter(a=>showH||a.element!=='H'),all=shown.length?shown:draft.atoms;
 const minX=Math.min(0,...all.map(a=>a.x)),maxX=Math.max(0,...all.map(a=>a.x)),minY=Math.min(0,...all.map(a=>a.y)),maxY=Math.max(0,...all.map(a=>a.y)),scale=Math.min(70,300/Math.max(1,maxX-minX),230/Math.max(1,maxY-minY));const cx=(minX+maxX)/2,cy=(minY+maxY)/2;
 svg.dataset.scale=scale;svg.dataset.cx=cx;svg.dataset.cy=cy;const points=new Map(shown.map(a=>[a.index,{x:250+(a.x-cx)*scale,y:180-(a.y-cy)*scale}]));
 svg.innerHTML=draft.bonds.map((b,i)=>{const a=points.get(b.from),c=points.get(b.to);if(!a||!c)return '';const length=Math.hypot(c.x-a.x,c.y-a.y)||1,dx=-(c.y-a.y)/length,dy=(c.x-a.x)/length;return `<g data-bond="${i}"><line class="micro-bond-hit" x1="${a.x}" y1="${a.y}" x2="${c.x}" y2="${c.y}"/>${Array.from({length:b.order},(_,k)=>{const offset=(k-(b.order-1)/2)*5;return `<line x1="${a.x+dx*offset}" y1="${a.y+dy*offset}" x2="${c.x+dx*offset}" y2="${c.y+dy*offset}"/>`;}).join('')}</g>`;}).join('')+shown.map(a=>{const p=points.get(a.index);return `<g data-atom="${a.index}" role="button" tabindex="0" aria-label="原子 ${a.element} ${a.index+1}" class="${a.index===selected||a.index===bondStart?'selected':''}"><circle cx="${p.x}" cy="${p.y}" r="15"/><text x="${p.x}" y="${p.y+5}" text-anchor="middle">${a.element}</text></g>`;}).join('');
 d.querySelector('[data-micro-name]').value=draft.name;d.querySelector('[data-micro-formula]').textContent=moleculeFormula(draft)||'空分子';d.querySelector('.micro-edit-error').textContent='';viewer.update(draft);sync();
 }
 function choose(index){if(tool==='erase'){remember();removeAtom(draft,index);selected=null;bondStart=null;}else if(tool==='atom'){remember();draft.atoms[index].element=element;selected=index;}else if(['single','double','triple'].includes(tool)){selected=index;if(bondStart===null)bondStart=index;else if(bondStart!==index){remember();const order={single:1,double:2,triple:3}[tool],existing=draft.bonds.find(b=>b.from===bondStart&&b.to===index||b.to===bondStart&&b.from===index);if(existing)existing.order=order;else draft.bonds.push({from:bondStart,to:index,order});bondStart=null;}}else selected=index;draw();}
 svg.addEventListener('click',e=>{if(drag?.moved)return;const atom=e.target.closest('[data-atom]'),bond=e.target.closest('[data-bond]');if(atom){choose(Number(atom.dataset.atom));return;}if(bond&&tool==='erase'){remember();draft.bonds.splice(Number(bond.dataset.bond),1);draw();return;}if(tool==='atom'){if(draft.atoms.length>=100)return;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());remember();draft.atoms.push({element,x:(p.x-250)/Number(svg.dataset.scale)+Number(svg.dataset.cx),y:(180-p.y)/Number(svg.dataset.scale)+Number(svg.dataset.cy),z:0});selected=draft.atoms.length-1;draw();}else{selected=null;draw();}});
 svg.addEventListener('keydown',e=>{const atom=e.target.closest('[data-atom]');if(atom&&(e.key==='Enter'||e.key===' ')){e.preventDefault();choose(Number(atom.dataset.atom));}});
 svg.addEventListener('pointerdown',e=>{const atom=e.target.closest('[data-atom]');if(tool!=='select'||!atom||e.button!==0)return;drag={id:Number(atom.dataset.atom),x:e.clientX,y:e.clientY,initial:structuredClone(draft.atoms[Number(atom.dataset.atom)]),moved:false};svg.setPointerCapture(e.pointerId);});
 svg.addEventListener('pointermove',e=>{if(!drag)return;const box=svg.getBoundingClientRect();if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4){remember();drag.moved=true;}if(drag.moved){const a=draft.atoms[drag.id];a.x=drag.initial.x+(e.clientX-drag.x)*500/box.width/Number(svg.dataset.scale);a.y=drag.initial.y-(e.clientY-drag.y)*360/box.height/Number(svg.dataset.scale);selected=drag.id;draw();}});
 const release=e=>{if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);const current=drag;drag=null;if(current&&!current.moved){selected=current.id;draw();}if(current)svg.addEventListener('click',event=>event.stopImmediatePropagation(),{capture:true,once:true});};svg.addEventListener('pointerup',release);svg.addEventListener('pointercancel',release);
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.element){element=b.dataset.element;setTool('atom');return;}const action=b.dataset.microAction;if(!action)return;if(['select','atom','erase','single','double','triple'].includes(action)){setTool(action);return;}if(action==='undo'&&undo.length){redo.push(structuredClone(draft));draft=undo.pop();}if(action==='redo'&&redo.length){undo.push(structuredClone(draft));draft=redo.pop();}if(action==='clear'){remember();draft.atoms=[];draft.bonds=[];}if(action==='ring'){remember();draft=createMolecule('benzene');d.querySelector('[data-micro-name]').value=draft.name;}selected=null;bondStart=null;draw();});
 d.querySelector('[data-show-h]').onchange=e=>{showH=e.target.checked;draw();};d.querySelector('[data-micro-preset]').onchange=e=>{if(!e.target.value)return;remember();draft=createMolecule(e.target.value);d.querySelector('[data-micro-name]').value=draft.name;selected=null;bondStart=null;draw();};d.querySelector('[data-micro-name]').onchange=e=>{remember();draft.name=e.target.value;draw();};
 d.querySelector('[data-apply-molecule]').onclick=()=>{if(readOnly)return;draft.name=d.querySelector('[data-micro-name]').value.trim();const error=validateMolecule(draft);if(error){d.querySelector('.micro-edit-error').textContent=error;return;}onApply?.(structuredClone(draft));d.close();};d.addEventListener('close',()=>viewer.destroy(),{once:true});draw();if(readOnly){d.classList.add('micro-modeling-readonly');d.querySelectorAll('.micro-2d-panel button,.micro-2d-panel input,.micro-2d-panel select').forEach(el=>el.disabled=true);svg.style.pointerEvents='none';svg.setAttribute('tabindex','-1');d.querySelector('[data-apply-molecule]').hidden=true;d.querySelector('.micro-modeling-footer [data-dialog-close]').textContent='关闭';d.querySelector('.micro-modeling-header p').append(' · 已完成节点，只读查看');}return d;
}
